const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const lon = -0.819876;
    const lat = 53.083908;
    const roi = ee.Geometry.Point([lon, lat]).buffer(5000); // 5 km radius

    const dateA = '2024-01-04';
    const dateB = '2022-01-05';

    // Helper: build S1 collection for a date with a window (±windowDays; 0 means [d, d+1))
    function getS1Collection(dateStr, windowDays) {
      const d = ee.Date(dateStr);
      const start = windowDays === 0 ? d : d.advance(-windowDays, 'day');
      const end = windowDays === 0 ? d.advance(1, 'day') : d.advance(windowDays + 1, 'day');
      const col = ee.ImageCollection('COPERNICUS/S1_GRD')
        .filterBounds(roi)
        .filterDate(start, end)
        .filter(ee.Filter.eq('instrumentMode', 'IW'))
        .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
        .filter(ee.Filter.eq('orbitProperties_pass', 'ASCENDING').or(ee.Filter.eq('orbitProperties_pass', 'DESCENDING')));
      return { col, start, end };
    }

    async function prepareComposite(dateStr) {
      // Try exact day
      let attempt = getS1Collection(dateStr, 0);
      let size = await attempt.col.size().getInfo();
      let usedWindow = 0;
      if (size === 0) {
        // Fallback ±3 days
        attempt = getS1Collection(dateStr, 3);
        size = await attempt.col.size().getInfo();
        usedWindow = 3;
      }
      return { size, usedWindow, col: attempt.col, start: attempt.start, end: attempt.end };
    }

    async function computeWaterStats(dateStr, label) {
      const prep = await prepareComposite(dateStr);
      if (prep.size === 0) {
        console.log(`${label} Images: 0`);
        return { status: 'C1' };
      }
      // Composite (median)
      const comp = prep.col.median().clip(roi);
      // VV to dB with small floor
      const vv = comp.select('VV');
      const vvDb = vv.max(1e-6).log10().multiply(10).rename('VVdB');

      // Threshold: 10th percentile dB within ROI
      const pDict = await vvDb.reduceRegion({
        reducer: ee.Reducer.percentile([10]),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9,
      }).getInfo();
      const thresh = pDict ? pDict['VVdB_p10'] : null;
      if (thresh === null || Number.isNaN(thresh)) {
        console.log(`${label} Threshold: NaN`);
        return { status: 'C3' };
      }

      // Water mask
      const water = vvDb.lt(thresh);

      // Valid pixel count and water pixel count (at 1 km scale for robustness/speed)
      const validCount = await vvDb.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9,
      }).get('VVdB').getInfo();

      if (!validCount || validCount === 0) {
        console.log(`${label} Valid px: 0`);
        return { status: 'C2' };
      }

      const waterPx = await water.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9,
      }).get('VVdB').getInfo();

      // Area in km2
      const waterAreaM2 = await ee.Image.pixelArea().updateMask(water).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9,
      }).get('area').getInfo();

      if (waterAreaM2 === null || Number.isNaN(waterAreaM2)) {
        console.log(`${label} Area: NaN`);
        return { status: 'C3' };
      }

      const waterKm2 = waterAreaM2 / 1e6;

      console.log(`${label} Images: ${prep.size} (±${prep.usedWindow}d)`);
      console.log(`${label} Valid px: ${validCount}, Water px: ${waterPx || 0}`);
      console.log(`${label} Water km2: ${waterKm2.toFixed(3)}, Thr_dB: ${thresh.toFixed(2)}`);

      return { status: 'OK', waterKm2, meta: { size: prep.size, window: prep.usedWindow } };
    }

    // 2. Run both dates
    const resA = await computeWaterStats(dateA, '2024-01-04');
    if (resA.status !== 'OK') {
      console.log(resA.status);
      return;
    }
    const resB = await computeWaterStats(dateB, '2022-01-05');
    if (resB.status !== 'OK') {
      console.log(resB.status);
      return;
    }

    // 3. Final comparison and answer
    const a = resA.waterKm2;
    const b = resB.waterKm2;

    if (a === null || b === null || Number.isNaN(a) || Number.isNaN(b)) {
      console.log('C3');
      return;
    }

    // Print concise summary
    console.log(`Compare (km2): 2024=${a.toFixed(3)} vs 2022=${b.toFixed(3)}`);

    if (a > b) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
